package net.minecraft.network.syncher;import java.util.*;public class SynchedEntityData {public Map<Object,Object> values=new HashMap<>();public static Object defineId(Class<?> c,Object serializer){return new Object();}public Object get(Object key){return values.getOrDefault(key,0);}public void set(Object key,Integer value){values.put(key,value);}public static class Builder {public SynchedEntityData data;public Builder(SynchedEntityData d){data=d;}public void define(Object key,Integer value){data.values.put(key,value);}}}